ALTER TYPE "JobStatus" ADD VALUE IF NOT EXISTS 'PENDING';
ALTER TYPE "JobStatus" ADD VALUE IF NOT EXISTS 'RETRYING';
ALTER TYPE "JobStatus" ADD VALUE IF NOT EXISTS 'COMPLETED';
ALTER TYPE "JobStatus" ADD VALUE IF NOT EXISTS 'REJECTED';
CREATE TYPE "ModerationStatus" AS ENUM ('PENDING', 'APPROVED', 'REJECTED', 'ERROR');
CREATE TYPE "AssetVisibility" AS ENUM ('PRIVATE', 'PUBLIC');
ALTER TABLE "Challenge" ADD COLUMN "nextAnonymousNumber" INTEGER NOT NULL DEFAULT 1;
UPDATE "Challenge" c SET "nextAnonymousNumber" = COALESCE((SELECT MAX(s."anonymousNumber") + 1 FROM "Submission" s WHERE s."challengeId" = c."id"), 1);
ALTER TABLE "GenerationJob" ADD COLUMN "errorCode" TEXT, ADD COLUMN "idempotencyKey" TEXT, ADD COLUMN "moderationStatus" "ModerationStatus" NOT NULL DEFAULT 'PENDING', ADD COLUMN "assetId" TEXT, ADD COLUMN "quotaDay" TEXT, ADD COLUMN "quotaFinalized" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "quotaRefunded" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "attempts" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE "Submission" ADD COLUMN "assetId" TEXT;
CREATE TABLE "GenerationQuota" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "day" TEXT NOT NULL, "reserved" INTEGER NOT NULL DEFAULT 0, "consumed" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "GenerationQuota_pkey" PRIMARY KEY ("id"));
CREATE TABLE "StoredAsset" ("id" TEXT NOT NULL, "provider" TEXT NOT NULL, "objectKey" TEXT NOT NULL, "publicObjectKey" TEXT, "mimeType" TEXT NOT NULL, "fileSize" INTEGER NOT NULL, "sha256" TEXT NOT NULL, "uploadStatus" TEXT NOT NULL, "visibility" "AssetVisibility" NOT NULL DEFAULT 'PRIVATE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "StoredAsset_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "GenerationQuota_userId_day_key" ON "GenerationQuota"("userId", "day");
CREATE UNIQUE INDEX "StoredAsset_objectKey_key" ON "StoredAsset"("objectKey");
CREATE UNIQUE INDEX "StoredAsset_publicObjectKey_key" ON "StoredAsset"("publicObjectKey");
CREATE INDEX "StoredAsset_sha256_idx" ON "StoredAsset"("sha256");
CREATE UNIQUE INDEX "GenerationJob_idempotencyKey_key" ON "GenerationJob"("idempotencyKey");
CREATE UNIQUE INDEX "GenerationJob_assetId_key" ON "GenerationJob"("assetId");
CREATE UNIQUE INDEX "Submission_assetId_key" ON "Submission"("assetId");
ALTER TABLE "GenerationQuota" ADD CONSTRAINT "GenerationQuota_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "GenerationJob" ADD CONSTRAINT "GenerationJob_assetId_fkey" FOREIGN KEY ("assetId") REFERENCES "StoredAsset"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Submission" ADD CONSTRAINT "Submission_assetId_fkey" FOREIGN KEY ("assetId") REFERENCES "StoredAsset"("id") ON DELETE SET NULL ON UPDATE CASCADE;
